// Read the form submission (or the TEST sample) and build the AI input. Iterates all items.
const MAX = 6000;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let content = String(j.Content || j.content || '').trim();
  if (content.length > MAX) content = content.slice(0, MAX) + ' …[truncated]';
  const tone = String(j.Tone || j.tone || 'Professional').trim();
  const brand = String(j.Brand || j.brand || '').trim();
  out.push({ json: {
    content, tone, brand,
    sourcePreview: content.slice(0, 120),
    createdAt: $now.toISO(),
    aiInput: `TONE: ${tone}\nBRAND/VOICE: ${brand || '(none given)'}\n\nSOURCE CONTENT:\n${content}`
  }});
}
return out;

// Honest guardrail: coerce arrays, verify every platform got real content, flag thin output.
// Pairs each AI item with its source by position (extractor emits one item per input, in order).
const preps = $('Prepare content').all();
const items = $input.all();
const asArr = v => Array.isArray(v) ? v : (v ? String(v).split('\n').filter(Boolean) : []);
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = items[i].json;
  const ai = (src && typeof src.output === 'object' && src.output) ? src.output : src;
  const prep = (preps[i] || preps[0] || { json: {} }).json;
  const hook = String(ai.hook || '').trim();
  const linkedin = String(ai.linkedin_post || '').trim();
  const xThread = asArr(ai.x_thread).map(s => String(s).trim()).filter(Boolean);
  const ig = String(ai.instagram_caption || '').trim();
  const news = String(ai.newsletter_blurb || '').trim();
  const tags = asArr(ai.hashtags).map(s => '#' + String(s).trim().replace(/^#+/, '')).filter(t => t.length > 1);
  const takeaway = String(ai.key_takeaway || '').trim();
  const lang = String(ai.detected_language || '').trim();
  const needsReview = !(hook && linkedin && xThread.length >= 2 && news && tags.length >= 1);
  out.push({ json: {
    createdAt: prep.createdAt, brand: prep.brand, tone: prep.tone,
    sourcePreview: prep.sourcePreview, detectedLanguage: lang,
    hook, linkedinPost: linkedin,
    xThread: xThread.join('\n\n'), xThreadCount: xThread.length,
    instagramCaption: ig, newsletterBlurb: news,
    hashtags: tags.join(' '), keyTakeaway: takeaway,
    needsReview, repurposeVersion: 'perly-content-repurposer-v1.0'
  }});
}
return out;
